/* Le bandeau de pagination est un calque plein largeur en z-index 10 :
   sans ceci il absorbe les clics des elements situes en bas de carte. */
.swiper-pagination {
  pointer-events: none !important;
}
/* Personnalisation des points de pagination */ .swiper-pagination-bullet {
  background: #000000 !important;
  opacity: 0.7 !important;
}  .swiper-pagination-bullet-active {
  background: #FFFFFF !important;
  opacity: 1 !important;
}

